@startuml

class HospitalHouseMD {
  + name : string
}

class Patient {
  + name : string
  + symptoms : string
}

class Doctor {
  + name : string
  + practitionerNumber : int
}

class Diagnosis {
  + description : string
}

class Treatment {
  + name : string
}

class TreatmentStage {
  + level : int
}

enum PriorityScore {
  High
  Low
}

class Illness {
  + name : string
  + priority : PriorityScore
}

class ConsentForm {
  + dateSigned : date
  + dateRetracted : date
}

class TreatmentRecord {
  + status : string
}

HospitalHouseMD "1" o-- "*" Patient
Patient "1" -- "1..*" Doctor
Doctor "1" -- "*" Diagnosis
Patient "1" -- "*" TreatmentRecord
Diagnosis "1" -- "*" TreatmentRecord
Illness "1" -- "*" Diagnosis
Illness "1" -- "*" Treatment
Treatment "1" -- "*" TreatmentRecord
TreatmentRecord "1" -- "1" TreatmentStage
TreatmentRecord "1" -- "0..1" ConsentForm
Doctor "1" -- "0..*" TreatmentRecord
Doctor "1" -- "0..*" ConsentForm

@enduml

